export type SessionId = string

/**
 * Profile de transcode suportado pelo backend. Fixo no código (não configurável via
 * `Setting`): `WEB` (navegador, hls.js), `TV` (TV/set-top box genérica), `MOBILE`
 * (dispositivo móvel), `GOOGLE_TV_STREAMER` (Google TV Streamer — H.264 até o nível 5.2,
 * HEVC Main/Main10 até o nível 5.1 ou AV1 Main até o nível 5.1, cap de 4K/60fps, áudio
 * AAC). `WEB`/`TV`/`MOBILE` resolvem pra mesma estratégia de transcode internamente (sem
 * diferenciação real de comportamento ainda); `GOOGLE_TV_STREAMER` tem estratégia própria.
 * O valor correto é o que descreve o dispositivo do cliente.
 */
export type TranscodeProfile =
  (typeof TranscodeProfile)[keyof typeof TranscodeProfile]

export const TranscodeProfile = {
  WEB: 'WEB',
  TV: 'TV',
  MOBILE: 'MOBILE',
  GOOGLE_TV_STREAMER: 'GOOGLE_TV_STREAMER',
} as const

