export interface SwitchTracksRequest {
  /**
   * Instante alvo, em segundos a partir do início da mídia
   * @minimum 0
   */
  positionSeconds: number
  /**
   * Posição (0-based) da faixa no array `audio` do `GET /v1/mediaprobe/files/{fileId}` —
   * **não** o campo `index` da faixa. Mesma semântica de `StartPlaybackSessionRequest`.
   * @minimum 0
   */
  audioTrackIndex: number
  /**
   * Posição (0-based) da faixa no array `subtitles` do `GET /v1/mediaprobe/files/{fileId}`
   * — **não** o campo `index` da faixa. Ausente/`null` reproduz sem legenda. Mesma
   * semântica de `StartPlaybackSessionRequest`.
   * @minimum 0
   * @nullable
   */
  subtitleTrackIndex?: number | null
}

/**
 * Sessão de playback recém-iniciada ou reposicionada
 */
export interface PlaybackSessionResponse {
  sessionId: SessionId
  /**
   * URL (relativa ao host) da playlist `m3u8` da sessão — atalho para o endpoint
   * `GET /v1/playback/sessions/{sessionId}/playlist.m3u8`.
   */
  playlistUrl: string
  /**
   * Posição de mídia, em segundos, que corresponde ao início da playlist (`currentTime 0`). O
   * cliente mapeia a posição local com base nela (`currentTime = alvo - startOffsetSeconds`) e
   * recarrega a source quando ela muda entre chamadas de seek (indicando que o transcode
   * reiniciou num novo offset). `0` no início da mídia.
   * @minimum 0
   */
  startOffsetSeconds: number
}

/**
 * Conteúdo da playlist HLS (`m3u8`) em texto
 */
export type M3u8Playlist = string

/**
 * Nome de um arquivo HLS da sessão. Formatos aceitos:
 *
 * - `segment_N.ts` / `segment_N.m4s` — segmento da rendition única (MPEG-TS ou fMP4);
 * - `segment_V_N.ts` / `segment_V_N.m4s` — segmento da variante `V` (ABR ou legenda soft);
 * - `init.mp4` — init segment fMP4 (via `#EXT-X-MAP`);
 * - `stream_V.m3u8` — variant playlist da variante `V`;
 * - `stream_V_vtt.m3u8` — playlist da rendition de legenda WebVTT;
 * - `stream_VN.vtt` — segmento de legenda WebVTT.
 *
 * Nome fora desses formatos responde `404` (não `400`) — por isso não há `pattern` aqui.
 */
export type MediaFileName = string

/**
 * Bytes de um arquivo HLS da sessão (segmento `.ts`/`.m4s`, init segment `.mp4`, playlist
 * `.m3u8` ou legenda `.vtt`)
 */
export type MediaFileContent = Blob

/**
 * Validade da sessão após o heartbeat
 */
export interface SessionHeartbeat {
  /**
   * Segundos restantes até a sessão expirar caso nenhum novo heartbeat chegue. O cliente
   * deve pingar novamente antes disso.
   * @minimum 0
   */
  expiresInSeconds: number
}

