  /**
   * Logo; URL absoluta quando há override manual
   * @nullable
   */
  logo?: string | null
  /** @nullable */
  episodes?: number | null
  /**
   * Duração média por episódio (formato livre)
   * @nullable
   */
  duration?: string | null
  /** @nullable */
  year?: number | null
  /**
   * Formato do anime (`TV`, `MOVIE`, `OVA`, ...)
   * @nullable
   */
  format?: string | null
  /**
   * Estação de estreia (`WINTER`, `SPRING`, ...)
   * @nullable
   */
  season?: string | null
  /**
   * Estúdio principal responsável pela produção, segundo a AniList
   * @nullable
   */
  studio?: string | null
  /**
   * Nota média em escala 0–10
   * @nullable
   */
  score?: number | null
  /**
   * Flag NSFW
   * @nullable
   */
  isAdult?: boolean | null
  /** @nullable */
  genres?: string[] | null
  franchiseRootCuration: FranchiseRootCuration
  /** `null` até o auto-bind terminar de processar a pasta pela primeira vez */
